using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using PokemonMvc.Data;using PokemonMvc.Models;namespace PokemonMvc.Controllers;public class CardsController(PokemonContext db,IWebHostEnvironment env):Controller{public async Task<IActionResult> Index(string? search){var q=db.Cards.AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Name.Contains(search)||x.CardNumber.Contains(search));return View(await q.OrderBy(x=>x.Name).ToListAsync());}public async Task<IActionResult> Details(int id){var c=await db.Cards.FindAsync(id);return c==null?NotFound():View(c);}public IActionResult Create()=>View(new Card());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Create(Card card,IFormFile? photo){if(!ModelState.IsValid)return View(card);await Save(card,photo);db.Cards.Add(card);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}public async Task<IActionResult> Edit(int id){var c=await db.Cards.FindAsync(id);return c==null?NotFound():View(c);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(int id,Card card,IFormFile? photo){if(id!=card.Id)return BadRequest();if(!ModelState.IsValid)return View(card);await Save(card,photo);db.Update(card);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}public async Task<IActionResult> Delete(int id){var c=await db.Cards.FindAsync(id);return c==null?NotFound():View(c);}[HttpPost,ActionName("Delete"),ValidateAntiForgeryToken]public async Task<IActionResult> DeleteConfirmed(int id){var c=await db.Cards.FindAsync(id);if(c!=null){db.Remove(c);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}private async Task Save(Card c,IFormFile? f){if(f==null||f.Length==0)return;var ext=Path.GetExtension(f.FileName).ToLowerInvariant();if(!new[]{".jpg",".jpeg",".png",".webp"}.Contains(ext))return;var dir=Path.Combine(env.WebRootPath,"uploads");Directory.CreateDirectory(dir);var n=Guid.NewGuid()+ext;using var s=System.IO.File.Create(Path.Combine(dir,n));await f.CopyToAsync(s);c.ImageUrl="/uploads/"+n;}}